#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct Node {
    long value;
    struct Node *left;
    struct Node *right;
} Node;

static Node *new_node(long v)
{
    Node *n = malloc(sizeof(Node));
    if (!n) {
        perror("malloc");
        exit(1);
    }
    n->value = v;
    n->left = n->right = NULL;
    return n;
}

static Node *insert(Node *root, long v)
{
    if (!root) return new_node(v);
    if (v < root->value) {
        root->left = insert(root->left, v);
    } else if (v > root->value) {
        root->right = insert(root->right, v);
    }
    // if equal, do nothing (ignore duplicates)
    return root;
}

static void print_space_if_needed(bool *first)
{
    if (!*first) {
        putchar(' ');
    } else {
        *first = false;
    }
}

static void inorder(Node *root, bool *first)
{
    if (!root) return;
    inorder(root->left, first);
    print_space_if_needed(first);
    printf("%ld", root->value);
    inorder(root->right, first);
}

static void preorder(Node *root, bool *first)
{
    if (!root) return;
    print_space_if_needed(first);
    printf("%ld", root->value);
    preorder(root->left, first);
    preorder(root->right, first);
}

static void postorder(Node *root, bool *first)
{
    if (!root) return;
    postorder(root->left, first);
    postorder(root->right, first);
    print_space_if_needed(first);
    printf("%ld", root->value);
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID_MODE");
        return 0;
    }

    const char *mode = argv[1];
    bool valid = strcmp(mode, "in") == 0 || strcmp(mode, "pre") == 0 || strcmp(mode, "post") == 0;
    if (!valid) {
        puts("INVALID_MODE");
        return 0;
    }

    Node *root = NULL;
    for (int i = 2; i < argc; ++i) {
        char *end;
        long v = strtol(argv[i], &end, 10);
        if (*end != '\0') continue; // ignore non‑numeric arguments
        root = insert(root, v);
    }

    if (!root) {
        puts("EMPTY");
        return 0;
    }

    bool first = true;
    if (strcmp(mode, "in") == 0) {
        inorder(root, &first);
    } else if (strcmp(mode, "pre") == 0) {
        preorder(root, &first);
    } else { // post
        postorder(root, &first);
    }
    putchar('\n');
    return 0;
}
